#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    const int MAX_STACK = 64;
    long long stack[MAX_STACK];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        if (strcmp(tok, "+") == 0 || strcmp(tok, "-") == 0 || strcmp(tok, "*") == 0 || strcmp(tok, "/") == 0) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long long b = stack[--top];
            long long a = stack[--top];
            long long res;
            if (strcmp(tok, "+") == 0) {
                res = a + b;
            } else if (strcmp(tok, "-") == 0) {
                res = a - b;
            } else if (strcmp(tok, "*") == 0) {
                res = a * b;
            } else { // "/"
                if (b == 0) {
                    puts("ERROR");
                    return 0;
                }
                res = a / b;
            }
            stack[top++] = res;
        } else {
            char *endptr;
            long long val = strtol(tok, &endptr, 10);
            if (endptr == tok || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }
            if (top >= MAX_STACK) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }

    if (top != 1) {
        puts("ERROR");
        return 0;
    }

    printf("%lld\n", stack[0]);
    return 0;
}
